insert into public.od_reports
  (period_id, slug, code, name, summary, description, image_url, image_alt, image_credit, line, note, position, status)
values
  ((select id from public.od_periods where label = '2020-2025'), 'diversidad-equidad-inclusion', 'DE', 'Diversidad, Equidad e Inclusión', 'Quiénes integran los grupos de protección constitucional y cómo los reconoce la universidad.', 'Estudiantes con pertenencia étnica, con discapacidad, afectados por el conflicto armado, de zona rural y de los estratos más bajos, contados campus a campus en el segundo periodo de cada año, junto con el Índice de Inclusión para la Educación Superior (INES) del Ministerio de Educación Nacional.', '', '', '', 10, 'Las categorías con menos de 5 registros se publican como «< 5»: en un campus pequeño, la cifra exacta señalaría a personas concretas. Los totales siguen siendo exactos. La sede de Bogotá se cuenta dentro de Bucaramanga.', 10, 'publicado'),
  ((select id from public.od_periods where label = '2020-2025'), 'bienestar-institucional', 'BI', 'Bienestar Institucional', 'Qué servicios de bienestar usan los estudiantes y quién paga la matrícula.', 'Cobertura de los servicios de deporte, actividad física y formación artística, y origen de la financiación de la matrícula, según la caracterización estudiantil multicampus.', '', '', '', 11, 'Estas cifras salen de una encuesta de caracterización, no de la matrícula: la base de cada porcentaje es quien respondió ese año. Lo que mide permanencia y acompañamiento académico vive en el informe Permanencia y no se repite aquí.', 11, 'publicado')
